(()=>{const D={"ko": {"title": "시장은 뛰는데 내 지갑은 왜 가볍지?", "line": "주가의 반등이 가계의 여유는 아니다.", "meaning": "주가 반등과 가계 구매력의 차이를 그린 논평·상징적 풍자입니다. 인물과 장면은 상징이며 실제 발언이나 특정 가정의 소득을 나타내지 않습니다.", "heading": "11/28 · 만평", "image": "https://lh3.googleusercontent.com/d/10qBP5tgwhBt8zV6WKOEQVSvhMcxu2mr3", "href": "archive/2026-11-28-cartoon.html"}, "en": {"title": "Markets bounce. Why is my wallet so light?", "line": "A market rebound is not household spending power.", "meaning": "Commentary and symbolic satire on the gap between a market rebound and household purchasing power. The figures and scene are symbolic, not actual quotations or the income of a particular family.", "heading": "11/28 · Editorial cartoon", "image": "https://lh3.googleusercontent.com/d/1w0sclq-0TJifsujC37Q0D-BgY1suCxLU", "href": "archive/2026-11-28-cartoon-en.html"}, "ja": {"title": "株価は跳ねるのに 財布はなぜ軽い？", "line": "株価の反発は、家計の余裕とは別だ。", "meaning": "株価反発と家計の購買力の差を描く論評・象徴的風刺。人物と場面は象徴で、実際の発言や特定家庭の所得ではありません。", "heading": "11/28 · 風刺漫画", "image": "https://lh3.googleusercontent.com/d/1VCgLNyPmexJI-3oM5tmDhLdt3mtDinT1", "href": "archive/2026-11-28-cartoon-ja.html"}, "zh": {"title": "市场反弹了 钱包怎么还这么轻？", "line": "股市反弹，不等于家庭购买力增加。", "meaning": "描绘股市反弹与家庭购买力差距的评论和象征性讽刺。人物和场景是象征，不是实际发言，也不代表特定家庭的收入。", "heading": "11/28 · 讽刺漫画", "image": "https://lh3.googleusercontent.com/d/19H4UcTwWHPvPUC3i_8_ne20Ul6HeCaOo", "href": "archive/2026-11-28-cartoon-zh.html"}, "es": {"title": "La bolsa rebota. ¿Por qué pesa tan poco mi cartera?", "line": "Un rebote bursátil no es poder adquisitivo familiar.", "meaning": "Comentario y sátira simbólica sobre la diferencia entre un rebote bursátil y el poder adquisitivo familiar. Los personajes y la escena son simbólicos, no citas reales ni los ingresos de una familia concreta.", "heading": "11/28 · Viñeta editorial", "image": "https://lh3.googleusercontent.com/d/1BvgDMlpwheJGIjjqxPsvvX5KY3vygPr0", "href": "archive/2026-11-28-cartoon-es.html"}};const f=document.getElementById('nr-daily-cartoon');if(!f)return;let last='';function apply(){const l=document.documentElement.dataset.lang||'ko';if(last===l)return;last=l;const z=D[l]||D.en;f.lang=l;const h=f.querySelector('h2'),badge=h.querySelector('span');h.replaceChildren();if(badge)h.append(badge);h.append(z.heading);const a=f.querySelector('.today-cartoon-open');a.href=z.href;a.querySelector('img').src=z.image;a.querySelector('img').alt=z.title;const c=f.querySelector('figcaption');c.querySelector('strong').textContent=z.title;const p=c.querySelectorAll('p');p[0].textContent=z.line;p[1].textContent=z.meaning;}new MutationObserver(apply).observe(document.documentElement,{attributes:true,attributeFilter:['data-lang']});apply();})();